<!-- Interactive Script for Tab Switching, Radius Slider, & Card Selection -->
<script>
    document.addEventListener("DOMContentLoaded", () => {
      // Highlight active sidebar item dynamically if present in DOM
      const navLinks = document.querySelectorAll('aside nav a[data-path="geofence-and-sites"]');
      navLinks.forEach(link => {
        link.className = "flex items-center gap-space-sm px-space-md py-space-sm rounded-xl font-label-lg text-label-lg bg-primary text-on-primary shadow-sm";
      });

      // Tab Inspector logic
      const tabButtons = document.querySelectorAll('[data-tab-target]');
      const tabPanes = document.querySelectorAll('[data-tab-content]');
      tabButtons.forEach(btn => {
        btn.addEventListener('click', () => {
          const target = btn.getAttribute('data-tab-target');
          tabButtons.forEach(b => {
            b.classList.remove('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
            b.classList.add('text-on-surface-variant');
          });
          btn.classList.add('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
          btn.classList.remove('text-on-surface-variant');

          tabPanes.forEach(pane => {
            if (pane.id === target) {
              pane.classList.remove('hidden');
            } else {
              pane.classList.add('hidden');
            }
          });
        });
      });

      // Interactive Radius Slider Controller
      const radiusSlider = document.getElementById('geofenceRadiusInput');
      const radiusValueBadge = document.getElementById('radiusValueDisplay');
      const mapSafeCircle = document.getElementById('svgSafeZoneCircle');
      const mapBufferCircle = document.getElementById('svgBufferZoneCircle');
      const mapRadiusLabel = document.getElementById('mapRadiusLabelText');

      if (radiusSlider && radiusValueBadge) {
        const updateRadius = (val) => {
          const num = parseInt(val, 10);
          radiusSlider.value = num;
          radiusValueBadge.textContent = `${num} meters`;
          if (mapRadiusLabel) mapRadiusLabel.textContent = `${num}m Primary Allowed Radius`;
          
          // Scale visual SVG element
          const basePx = Math.max(50, Math.min(220, num * 0.9));
          if (mapSafeCircle) {
            mapSafeCircle.setAttribute('r', basePx);
          }
          if (mapBufferCircle) {
            mapBufferCircle.setAttribute('r', (basePx + 38).toString());
          }
        };

        radiusSlider.addEventListener('input', (e) => {
          updateRadius(e.target.value);
        });

        const stepDownBtn = document.getElementById('radiusStepDown');
        const stepUpBtn = document.getElementById('radiusStepUp');
        if (stepDownBtn) {
          stepDownBtn.addEventListener('click', () => {
            let cur = parseInt(radiusSlider.value, 10);
            if (cur > 20) updateRadius(cur - 10);
          });
        }
        if (stepUpBtn) {
          stepUpBtn.addEventListener('click', () => {
            let cur = parseInt(radiusSlider.value, 10);
            if (cur < 1000) updateRadius(cur + 10);
          });
        }
      }

      // Map Style buttons toggle visual feedback
      const mapStyleBtns = document.querySelectorAll('.map-style-btn');
      mapStyleBtns.forEach(btn => {
        btn.addEventListener('click', () => {
          mapStyleBtns.forEach(b => {
            b.classList.remove('bg-primary', 'text-on-primary');
            b.classList.add('bg-surface-container-lowest/90', 'text-on-surface-variant');
          });
          btn.classList.add('bg-primary', 'text-on-primary');
          btn.classList.remove('bg-surface-container-lowest/90', 'text-on-surface-variant');
        });
      });
    });
  </script>
